describe('Page Number Navigation', () => {
  beforeEach(() => {
    cy.visit('/dashboard');
  });

  it('should navigate to the specified page using page number input', () => {
    // Verify initial page is displayed
    cy.get('[data-testid="page-number-input"]').should('be.visible');
    cy.get('[data-testid="page-number-input"]').type('5');
    cy.get('[data-testid="go-button"]').click();

    // Verify navigation to page 5
    cy.get('[data-testid="page-number-input"]').should('contain', '5');
    cy.get('[data-testid="current-page-number"]').should('contain', '5');
    cy.get('[data-testid="page-content"]').should('contain', 'Page 5 content');

    // Verify pagination controls are visible
    cy.get('[data-testid="pagination-controls"]').should('be.visible');
    cy.get('[data-testid="previous-page"]').should('be.visible');
    cy.get('[data-testid="next-page"]').should('be.visible');
  });

  it('should handle invalid page number input and show error message', () => {
    // Verify initial page is displayed
    cy.get('[data-testid="page-number-input"]').should('be.visible');

    // Attempt to navigate to a non-existent page (e.g., page 0)
    cy.get('[data-testid="page-number-input"]').type('0');
    cy.get('[data-testid="go-button"]').click();

    // Verify error message is displayed
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Page number out of range');

    // Verify pagination controls are still visible
    cy.get('[data-testid="pagination-controls"]').should('be.visible');

    // Verify navigation is not performed
    cy.get('[data-testid="current-page-number"]').should('contain', '1');
    cy.get('[data-testid="page-content"]').should('contain', 'Page 1 content');
  });
});
